/**
 * Typed access to the bundled N5 vocabulary (generated by tools/build_n5.py — do not edit n5.json by hand).
 */
import raw from './n5.json';

/** Ruby segment: `r` (reading) is only present over kanji. */
export type FuriganaSegment = { t: string; r?: string };

export type PartOfSpeech =
  | 'noun'
  | 'verb'
  | 'i-adj'
  | 'na-adj'
  | 'adverb'
  | 'pronoun'
  | 'counter'
  | 'suffix'
  | 'prefix'
  | 'particle'
  | 'conjunction'
  | 'interjection'
  | 'expression'
  | 'pre-noun adj'
  | 'number'
  | 'other';

export type Example = {
  ja: FuriganaSegment[];
  en: string;
  /** Tatoeba sentence ids [japanese, english] (CC BY 2.0 FR attribution). */
  src: [number, number];
};

export type Word = {
  id: string;
  /** Frequency rank, 1 = most common: order in which new words are introduced. */
  rank: number;
  /** Written form shown on the card front (kana when the word is usually written in kana). */
  kanji: string;
  reading: string;
  furigana: FuriganaSegment[];
  meaning_en: string;
  pos: PartOfSpeech;
  pos_detail?: string;
  themes: string[];
  examples: Example[];
};

export type Theme = { id: string; name: string };

type Vocab = { version: number; sources: Record<string, string>; themes: Theme[]; words: Word[] };

// The JSON's inferred type is looser (number[] vs tuple); its shape is checked by vocab.test.ts.
export const vocab = raw as unknown as Vocab;
export const words: Word[] = vocab.words;
export const themes: Theme[] = vocab.themes;
